import { getSymbolicEngine } from '/Users/aidenybai/Developer/bippy-engine262-symbolic/packages/bippy-analyzer/src/symbolic/load-engine.ts';
import { createConcreteRuntime } from '/Users/aidenybai/Developer/bippy-engine262-symbolic/packages/bippy-analyzer/src/concrete/runtime.ts';
import { getNativeGcObservation } from '/Users/aidenybai/Developer/bippy-engine262-symbolic/packages/bippy-analyzer/tests/helpers/native-gc.ts';
const main = async () => {
  const { api } = await getSymbolicEngine();
  const previous = api.surroundingAgent;
  const agent = new api.Agent({ startEventLoop: false, onDebugger: () => {} });
  api.setSurroundingAgent(agent);
  const source = `var reference, retained; function create(){const target={value:7};reference=new WeakRef(target);return target;} function pause(){debugger;} retained=[create(),pause()];`;
  let externalDriver: unknown;
  try {
    const realm = new api.ManagedRealm();
    const compiled = api.EnsureCompletion(realm.compileScript(source));
    if (compiled.Type !== 'normal') throw new Error('Expected compiled script');
    const iterator = api.ScriptEvaluation(compiled.Value);
    let step = iterator.next();
    while (!step.done && step.value.suspend !== 'debugger') step = iterator.next({resume:'debugger',value:undefined});
    if (step.done) throw new Error('Expected debugger suspension');
    agent.AgentRecord.KeptAlive.clear();
    api.gc();
    const completed = api.EnsureCompletion(api.skipDebugger(iterator));
    if (completed.Type !== 'normal') throw new Error('Expected resumed completion');
    const observation = 'JSON.stringify([reference.deref() !== undefined, retained[0].value])';
    const result = api.EnsureCompletion(realm.evaluateScriptSkipDebugger(observation));
    if (result.Value.type !== 'String') throw new Error('Expected observation');
    externalDriver = { source, observation, engine: JSON.parse(result.Value.stringValue()), usesAgentEvaluate: false, fixed: false };
  } finally { api.setSurroundingAgent(previous); }
  const runtime = await createConcreteRuntime();
  const timerSource = `var reference, seen; (()=>{const target={value:7};reference=new WeakRef(target);setTimeout(()=>{seen=target.value;},0);})();`;
  let timer: unknown;
  try {
    runtime.evaluate(timerSource);
    api.setSurroundingAgent(runtime.agent);
    const pop = runtime.realm.pushTopContext();
    try { runtime.agent.AgentRecord.KeptAlive.clear(); api.gc(); }
    finally { pop?.(); api.setSurroundingAgent(previous); }
    runtime.drainJobs();
    const observation = 'JSON.stringify([reference.deref() !== undefined, seen])';
    const nativeSetup = `const pending=[]; const setTimeout=callback=>pending.push(callback); ${timerSource}`;
    const nativeObservation = `(pending.shift()(), ${observation})`;
    timer = { source: timerSource, observation, engine: JSON.parse(runtime.readString(observation)), native: JSON.parse(getNativeGcObservation(nativeSetup, nativeObservation)), nativeHost: 'Explicit retained callback queue, not browser timer scheduling parity', fixed: false };
  } finally { runtime.dispose(); api.setSurroundingAgent(previous); }
  console.log(JSON.stringify({ externalDriver, timer }, null, 2));
};
void main();
